namespace ghidra.feature.vt.gui.task;

using ghidra.feature.vt.api.db;
using ghidra.feature.vt.api.main;
using ghidra.util;
using ghidra.util.exception;
using ghidra.util.task;
using ghidra.util.task;



public class SetMarkupItemConsideredTask : Task {

	protected List<VTMarkupItem> markupItems;
	private VTSessionDB session;
	protected VTMarkupItemConsideredStatus status;

	public SetMarkupItemConsideredTask(VTSession session, List<VTMarkupItem> markupItems,
			VTMarkupItemConsideredStatus status) : this(status.name() + " Markup Items", session, markupItems, status)
    {
	}

	protected SetMarkupItemConsideredTask(string title, VTSession session,
			List<VTMarkupItem> markupItems, VTMarkupItemConsideredStatus status) : base(title, true, true, true, true)
    {
		this.markupItems = markupItems;

		if (!(session is VTSessionDB)) {
			throw new IllegalArgumentException(
				"Unexpected condition - VTSession is not a DB object!");
		}

		this.session = (VTSessionDB) session;
		this.status = status;
	}

	/* @Override */
	public void run(TaskMonitor monitor) {

		bool commit = true;

		int matchSetTransactionID = session.startTransaction(getTaskTitle());
		try {
			doWork(monitor);
		}
		catch (CancelledException e) {
			commit = false;
		}
		catch (Exception e) {
			commit = false;
			Msg.showError(this, null, "Unable to Apply Markup Item(s)",
				"An unexpected error occurred attempting to apply markup item(s).", e);
		}
		finally {
			session.endTransaction(matchSetTransactionID, commit);
		}
	}

	protected void doWork(TaskMonitor monitor)
    {
		monitor.initialize(markupItems.size());
		foreach (VTMarkupItem markupItem in markupItems) {
			monitor.checkCancelled();
			markupItem.setConsidered(status);
			monitor.incrementProgress(1);
		}
	}
}
